INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:electrician',true,'Electrical Contractor License #',ARRAY['State Electrical Licensing Board (jurisdiction-specific)','Local Building Department / Authority Having Jurisdiction (AHJ)','Occupational Safety and Health Administration (OSHA)','National Fire Protection Association (NFPA) — NEC Publisher']::text[],ARRAY['licensed in all 50 states','no permit required','guaranteed to pass inspection','OSHA compliant without documentation','we waive permit fees','unlicensed but insured is enough','code violations are no big deal','permits are optional for minor work']::text[],ARRAY['All electrical work performed in accordance with the current National Electrical Code (NEC) and applicable local amendments.','Permits required for panel upgrades, new circuit installation, and other work as specified by local building codes — homeowner or contractor must obtain prior to work commencement.','Journeyman and Master Electrician license numbers available upon request and as required by state law.','Commercial work performed in compliance with OSHA 29 CFR 1910 electrical safety standards.','AFCI protection installed per NEC 210.12 requirements where applicable.','Licensing requirements vary by state and municipality; verify contractor license status with your state licensing board.']::text[],false,false,false,ARRAY['Must not advertise services in jurisdictions where not licensed','Must not imply licensure status not held (e.g., Master Electrician) if only Journeyman-licensed','Must not guarantee permit approval or inspection pass outcomes','Must disclose if work is subcontracted to another licensed entity','Cannot advertise emergency availability without 24/7 verifiable response capability','Must not claim code compliance without specifying applicable NEC edition and local amendments']::text[])
