INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:church',false,NULL,ARRAY['IRS (Internal Revenue Service) — 501(c)(3) tax-exempt status','State Attorney General — nonprofit corporate compliance','State Secretary of State — nonprofit entity registration','Local Zoning and Planning Authority — RLUIPA land use','Local Fire Marshal and Building Code Authority — occupancy and safety']::text[],ARRAY['guaranteed salvation','IRS-approved religion','licensed church','state-certified congregation','official government-recognized faith','donations are always tax-deductible (without qualification)','we are exempt from all laws','no background checks required for volunteers']::text[],ARRAY['Tax-exempt status under IRS 501(c)(3) does not constitute government endorsement of religious beliefs','Charitable contribution deductibility is subject to IRS rules and individual circumstances; consult a tax advisor','This organization complies with applicable child protection laws including mandatory background checks for staff and volunteers working with minors','Occupancy limits are set by local fire and building codes and are strictly enforced']::text[],false,false,false,ARRAY['Must not imply government endorsement of religious doctrine','Must not make unqualified claims of tax deductibility for all donations','Must not misrepresent 501(c)(3) status as a government certification of religious legitimacy','Must comply with RLUIPA when advertising land use or facility expansion','Must not make false claims regarding child safety credentials or background check policies']::text[])
