INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:financial_planner',true,'CFP® Certification / Investment Adviser Registration / State License #',ARRAY['CFP Board of Standards','U.S. Securities and Exchange Commission (SEC)','FINRA (Financial Industry Regulatory Authority)','State Securities Regulators (via NASAA)','State Insurance Departments','U.S. Department of Labor (ERISA)']::text[],ARRAY['guaranteed returns','risk-free investment','we will make you rich','outperform the market guaranteed','no-risk portfolio','guaranteed income','beats inflation guaranteed','certain to grow','government-insured investment returns','free financial advice']::text[],ARRAY['Investment advisory services involve risk, including possible loss of principal.','This firm/individual is registered as an investment adviser with [SEC/State]. Registration does not imply a certain level of skill or training.','Form ADV Part 2 is available upon request and will be delivered prior to or at the time of entering an advisory agreement.','Compensation structure (fee-only, fee-based, commission) disclosed per SEC Regulation Best Interest.','CFP® professionals are held to a fiduciary standard when providing financial planning services.','Insurance products are offered through a separately licensed entity. State insurance license numbers available upon request.','ERISA fiduciary acknowledgment provided where applicable to retirement plan participants.','Past performance is not indicative of future results.']::text[],false,false,true,ARRAY['All performance claims must include standardized benchmark comparisons and time periods per SEC advertising rules.','Testimonials and endorsements in advertisements must comply with SEC Marketing Rule (Rule 206(4)-1).','CFP® mark usage must comply with CFP Board trademark and use policies.','No hypothetical performance results without required disclosures.','Social media posts constituting investment advice must comply with SEC recordkeeping and advertising rules.','No promissory language regarding investment outcomes.','Insurance product advertising subject to state insurance department approval requirements.','Third-party ratings or awards must disclose the criteria and compensation paid, if any.']::text[])
