INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:chiropractor',true,'DC License #',ARRAY['State Chiropractic Board (jurisdiction-specific, e.g. California Board of Chiropractic Examiners)','Federation of Chiropractic Licensing Boards (FCLB)','National Board of Chiropractic Examiners (NBCE)']::text[],ARRAY['guaranteed results','cure','we can cure your condition','permanent fix','better than surgery','replaces medical care','FDA approved treatment','scientifically proven to eliminate','no side effects','instant relief guaranteed']::text[],ARRAY['Chiropractic care is not a substitute for emergency medical treatment. Seek emergency care for serious injuries.','Individual results may vary. No specific outcome is guaranteed.','This practice complies with HIPAA. Your health information is protected.','Informed consent is required before initiating any chiropractic treatment.','X-ray services, if offered, are operated in compliance with applicable radiation safety regulations.','Malpractice insurance is maintained as required by state law.']::text[],false,true,false,ARRAY['Cannot claim to diagnose, treat, or cure specific diseases beyond scope of chiropractic practice in many states','Testimonials must comply with FTC endorsement guidelines and state board advertising rules','Cannot use the title ''MD'', ''Doctor of Medicine'', or imply medical doctor status','Before-and-after claims require substantiation and may be restricted by state board rules','Cannot advertise free services as a lure without clear disclosure of conditions','Must include DC license number in advertising where required by state law','Cannot make unsubstantiated superiority claims over other healthcare providers','Discount or free consultation offers must comply with state anti-kickback and fee-splitting rules']::text[])
