INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:lawyer',true,'State Bar License #',ARRAY['State Bar Association (jurisdiction-specific)','American Bar Association (ABA Model Rules of Professional Conduct)','State Supreme Court (attorney admission and discipline)','IOLTA program administrator (jurisdiction-specific trust account oversight)']::text[],ARRAY['guaranteed outcome','we will win your case','best lawyer in [city]','no one beats our results','guaranteed settlement','we never lose','instant legal advice','attorney-client relationship formed by visiting this page','certified specialist (without accredited certification)','free legal advice (without disclaimer)']::text[],ARRAY['This communication does not create an attorney-client relationship.','Prior results do not guarantee a similar outcome.','[Attorney Name] is licensed to practice law in [State(s)] only.','This website is for informational purposes only and does not constitute legal advice.','Contingency fee disclaimer where applicable: ''Fees are contingent on recovery; client responsible for costs.''','IOLTA trust account disclaimer where retainer funds are held.']::text[],false,false,true,ARRAY['State bar advertising rules govern all marketing materials and claims','Testimonials and endorsements must comply with state bar rules and include required disclaimers','Superlatives and comparative claims (e.g., ''best,'' ''top'') prohibited unless verifiably substantiated per state rules','Claims of specialization or certification require accreditation by a state bar or ABA-accredited body','Paid referral arrangements must comply with state fee-splitting and referral rules','Meta/Google ad copy subject to state bar review for misleading claims','No in-person or live telephone solicitation of prospective clients in most jurisdictions (Model Rule 7.3)','Spanish or multilingual advertising must carry equivalent disclaimers in all languages used']::text[])
