INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:insurance_agency',true,'State Insurance Agency License #',ARRAY['State Insurance Department (jurisdiction-specific, e.g., California Department of Insurance, New York Department of Financial Services)','National Association of Insurance Commissioners (NAIC)','Federal Trade Commission (FTC) — GLBA enforcement','Federal Communications Commission (FCC) — TCPA enforcement']::text[],ARRAY['guaranteed lowest rates','best price guaranteed','we always pay claims','guaranteed coverage approval','no medical exam required for all policies','guaranteed savings','government-mandated insurance plan','we are the only agency you need','unlimited coverage','zero out-of-pocket guaranteed','your claim will be approved','we beat every competitor''s price']::text[],ARRAY['Insurance products and services are subject to state availability and individual underwriting approval.','Coverage terms, conditions, exclusions, and limits vary by policy. Review your policy documents carefully.','This agency is licensed in [state(s)]. License number(s) available upon request.','Insurance quotes are estimates only and are not a guarantee of final premium or coverage.','Your personal and financial information is protected under the Gramm-Leach-Bliley Act (GLBA). See our Privacy Notice for details.','Errors and Omissions (E&O) insurance maintained as required by applicable state law.','Marketing communications comply with CAN-SPAM and TCPA regulations. Reply STOP to opt out of text messages.','State-mandated minimum coverage requirements may apply for auto, workers compensation, and other lines of insurance.']::text[],false,false,true,ARRAY['Must not use the word ''independent'' unless the agency is contractually independent from all carriers advertised','Must not imply government affiliation or endorsement','Must disclose carrier relationships and any compensation arrangements where required by state law','Must include agency license number in all print and digital advertising where required by state regulation','Must comply with TCPA prior express written consent requirements before sending marketing texts or robocalls','Must comply with CAN-SPAM Act for all commercial email marketing, including clear opt-out mechanisms','Must not make misleading comparisons of competitor products or pricing','Must adhere to NAIC model advertising guidelines for insurance products including accurate benefit representations','Must not guarantee claim outcomes or underwriting approval in advertising copy']::text[])
