INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:hotel',true,'State Lodging License #',ARRAY['State Department of Health / Division of Hotels and Restaurants','State Fire Marshal''s Office','Local Building and Zoning Authority','State Department of Revenue (Lodging Tax)','Payment Card Industry Security Standards Council (PCI DSS)','U.S. Department of Labor – OSHA','Americans with Disabilities Act (ADA) – U.S. Department of Justice','Local Health Department (Food Service Licensing)']::text[],ARRAY['guaranteed lowest rate','100% safe and secure','fully ADA compliant (without current certification)','we never share your payment data','fire-proof','immune to bedbugs','five-star (without official rating body certification)','best hotel in [city] (unsupported superlative)']::text[],ARRAY['State and local lodging taxes are collected at checkout and remitted to the applicable tax authority.','This property is required to comply with ADA accessibility standards; guests with accommodation needs should contact the property directly.','Food and beverage services are subject to local health department inspection and licensing requirements.','Payment card data is processed in accordance with PCI DSS standards; we do not store full card numbers.','Fire safety systems are inspected and maintained in accordance with state and local fire codes.','Rates and availability are subject to change without notice.']::text[],false,false,true,ARRAY['Star ratings may only be claimed if awarded by a recognized rating body (AAA, Forbes Travel Guide, etc.)','Accessibility claims must reflect current ADA audit status','Lodging tax must be disclosed in advertised rates where required by state law','''Best rate guarantee'' claims require documented price-match policy','Food safety grade or inspection score must not be misrepresented in advertising','OSHA violation history must not be concealed in safety-related marketing claims']::text[])
