INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:family_restaurant',true,'Food Service Permit #',ARRAY['Local/County Health Department','State Department of Health','U.S. Food and Drug Administration (FDA)','State Alcoholic Beverage Control Board (if applicable)','U.S. Department of Labor - Wage and Hour Division','State Labor Department']::text[],ARRAY['Guaranteed safe from foodborne illness','100% allergen-free','No health inspection required','Certified germ-free kitchen']::text[],ARRAY['Health inspection score/permit available upon request or as required by local law','Menu items may contain allergens; please inform your server of any dietary restrictions','Calorie information available for standard menu items at chain locations with 20 or more locations as required by FDA','Alcohol service subject to state and local liquor laws; valid ID required','Consuming raw or undercooked meats, poultry, seafood, shellfish, or eggs may increase your risk of foodborne illness']::text[],false,false,false,ARRAY['Do not advertise as allergen-free without documented protocols and certification','Do not claim health inspection scores selectively without current documentation','Calorie counts in advertising must match FDA-approved menu labeling figures for qualifying chains','Alcohol promotions must comply with state ABC advertising rules','Do not use imagery implying unlimited alcohol service where prohibited']::text[])
