INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:auto_repair_shop',true,'Auto Repair Dealer (ARD) License #',ARRAY['Bureau of Automotive Repair (BAR) – California (and equivalent state agencies in applicable jurisdictions)','U.S. Environmental Protection Agency (EPA)','Occupational Safety and Health Administration (OSHA)','Federal Trade Commission (FTC)','State Attorney General Consumer Protection Divisions']::text[],ARRAY['guaranteed lowest price on all repairs','we fix it right the first time guaranteed','no hidden fees ever','certified by all manufacturers','dealer-authorized for all makes and models','we beat any written estimate','lifetime guarantee on all parts and labor','EPA-certified shop (without valid certification)','our mechanics are the best in the state']::text[],ARRAY['Written estimates must be provided before work begins as required by applicable state automotive repair acts','Customer authorization is required before performing any repairs not listed on the original estimate','Final charges may not exceed the written estimate without prior customer approval','Replaced parts are available for customer inspection upon request','Refrigerant handling performed by EPA Section 608 certified technicians only','Used oil, coolant, and refrigerants disposed of in accordance with EPA regulations','Shop license number displayed as required by state Bureau of Automotive Repair or equivalent authority','Warranty terms and limitations provided in writing at time of service']::text[],false,false,false,ARRAY['Cannot advertise specific repair prices without disclosing all applicable fees and parts costs','Cannot claim manufacturer certification or dealer authorization without valid agreement','Cannot advertise EPA or ASE certifications not currently held by shop or technicians','Must include license number in advertising where required by state BAR or equivalent','Cannot use deceptive pricing that omits mandatory charges','FTC Used Car Rule disclosures required when repairs are performed in connection with used vehicle sales']::text[])
