INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:pediatric_dentist',true,'State Dental License #',ARRAY['State Dental Board (jurisdiction-specific)','American Academy of Pediatric Dentistry (AAPD)','American Dental Association (ADA)','Drug Enforcement Administration (DEA) — for controlled substance/sedation permits','State Board of Pharmacy (for offices dispensing medications)','OSHA (Occupational Safety and Health Administration)','State Health Department (facility/sedation permits)']::text[],ARRAY['guaranteed pain-free','100% safe sedation','best dentist for kids','certified as the safest pediatric office','no risk anesthesia','permanent results guaranteed','we cure cavities permanently','#1 pediatric dentist (without substantiation)','FDA-unapproved treatment claims']::text[],ARRAY['Licensed pediatric dentist in [State]. License # available upon request.','Sedation services are performed under state-licensed and permitted protocols. Risks will be discussed during consultation.','HIPAA Notice of Privacy Practices available at the office and upon request. Minor patient records are protected under applicable state and federal law.','Informed consent from a parent or legal guardian is required prior to any sedation or surgical procedure for minor patients.','Individual treatment outcomes may vary.','This office complies with OSHA Bloodborne Pathogen Standards and ADA/AAPD infection control guidelines.']::text[],false,true,false,ARRAY['Must not imply sedation is risk-free or routine without appropriate disclosure','Must not use superlative claims (e.g., ''best,'' ''safest,'' ''most trusted'') without verifiable substantiation','Must comply with FTC truth-in-advertising standards for before/after imagery','Must not advertise controlled substances or sedation medications by name in consumer-facing ads without regulatory compliance','Testimonials from parents must include disclaimer that results are not guaranteed','Must not market to minors directly in a manner that bypasses parental consent','State dental board advertising rules apply — must include license number in ads where required by jurisdiction']::text[])
