INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:real_estate_agents',true,'State Real Estate License #',ARRAY['State Real Estate Commission (jurisdiction-specific, e.g. California Department of Real Estate, Texas Real Estate Commission, New York Department of State Division of Licensing Services)','National Association of Realtors (NAR) Code of Ethics','Consumer Financial Protection Bureau (CFPB) — RESPA compliance for referral arrangements','U.S. Department of Housing and Urban Development (HUD) — Fair Housing Act enforcement']::text[],ARRAY['Guaranteed sale price','We guarantee your home will sell in X days','Best agent in [city] (superlative without substantiated basis)','Investment guaranteed returns','No commission','Free agent (implies no compensation structure)','We will beat any offer']::text[],ARRAY['Agent is licensed in [State]. License # [number].','Realtor® is a registered trademark of the National Association of Realtors.','All information deemed reliable but not guaranteed. Buyers and sellers should independently verify all data.','This is not a solicitation if your property is currently listed with another broker.','Equal Housing Opportunity. We are pledged to the letter and spirit of the U.S. policy for the achievement of equal housing opportunity throughout the nation.','Compensation is negotiable and not set by law. Buyer representation agreements required per NAR settlement rules effective August 2024.']::text[],false,false,true,ARRAY['Must disclose brokerage name on all advertising per state real estate commission rules','Cannot use the term Realtor® unless current NAR member','Must comply with CAN-SPAM and TCPA for email and SMS marketing campaigns','Fair Housing Act prohibits advertising language that indicates preference or limitation based on race, color, religion, sex, disability, familial status, or national origin','RESPA Section 8 prohibits kickbacks or unearned fees in connection with referral arrangements to settlement service providers','Must disclose material relationships with preferred vendors (lenders, title, inspectors) to clients','Social media advertising must include license number and brokerage name per most state commission rules']::text[])
