INSERT INTO exp_category_compliance (gcid,display_license_on_profile,license_display_format,regulated_by,prohibited_phrases,required_disclaimers,age_gate_required,hipaa_applies,glba_applies,content_restrictions) VALUES ('gcid:mortgage_broker',true,'NMLS # [number]',ARRAY['Consumer Financial Protection Bureau (CFPB)','Nationwide Multistate Licensing System & Registry (NMLS)','State Department of Financial Institutions / Division of Banking (jurisdiction-specific)','U.S. Department of Housing and Urban Development (HUD) — for FHA and HECM','U.S. Department of Veterans Affairs (VA) — for VA loan approval','USDA Rural Development — for USDA loan approval','Federal Trade Commission (FTC) — advertising and unfair practices']::text[],ARRAY['guaranteed approval','guaranteed lowest rate','we will match any rate guaranteed','no income verification required','all credit accepted','pre-approved regardless of credit','better than any bank guaranteed','zero closing costs guaranteed','rates as low as [X]% for all borrowers','instant mortgage approval']::text[],ARRAY['NMLS # [number] displayed on all advertising, websites, and business cards per SAFE Act','Equal Housing Lender or Equal Housing Opportunity logo required on all marketing materials','Rates and terms subject to change without notice; not a commitment to lend','Not all applicants will qualify; approval subject to underwriting','This is not a commitment to make a mortgage loan; subject to property appraisal and title','Reverse mortgage: borrowers must be 62+, maintain property, pay taxes and insurance; loan becomes due on sale or vacancy','APR and payment examples must reflect actual costs per Regulation Z / TRID','State licensing disclosure required in all states where originating loans','Affiliated business arrangement disclosure required under RESPA Section 8 where applicable','HMDA data collected and reported annually as required by federal law']::text[],false,false,true,ARRAY['All rate and payment advertising must comply with Regulation Z (Truth in Lending Act) triggering terms','UDAP (Unfair, Deceptive, or Abusive Acts or Practices) prohibition under CFPB authority','RESPA Section 8 prohibits kickbacks or unearned fees in settlement service referral arrangements','CAN-SPAM and TCPA compliance required for email and SMS marketing','Fair Housing Act prohibits steering or discriminatory marketing targeting','State-specific mortgage advertising disclosure laws may impose additional labeling requirements','Social media advertising must include NMLS ID and Equal Housing Lender disclosure','Testimonials and endorsements must comply with FTC Endorsement Guides (16 CFR Part 255)']::text[])
